recipe('thai-chicken-meatballs','Chicken meatballs with sweet chilli glaze',C,4,200,20,20,[[450,'chicken mince','F002739'],(50,'egg'),(60,'crumbs'),[25,'spring onion','F006250','Finely sliced'],[10,'fresh coriander','F003192','Chopped'],(5,'garlic','Grated'),(25,'honey'),(20,'vinegar'),(20,'ketchup'),(10,'lemon'),(5,'soy'),(1,'chilli')],['Mix chicken mince with egg, crumbs, spring onion, coriander and garlic. Shape sixteen balls of equal size, about 3 cm across.','Air fry in two uncrowded batches at 200°C for 10 minutes per batch, turning after 5 minutes, until the centres reach 74°C.','Simmer honey, vinegar, tomato sauce, lemon, soy and chilli in a small saucepan for 2 minutes. Toss cooked meatballs in the warm glaze and serve four per person.'],'Small chicken meatballs use coriander and spring onion for freshness beneath a tangy chilli glaze.',internal=74,allergens=['egg','wheat','gluten','soy'],equipment=['Small saucepan'],nutritionNote='A measured honey-chilli glaze replaces commercial sweet chilli sauce. All sauce counted; two sequential batches included.')
recipe('pandan-leaf-chicken','Pandan-wrapped chicken parcels',C,4,200,25,18,[(500,'thigh','Cut into eight even boneless pieces'),(60,'onion','Chopped'),(15,'garlic'),(10,'ginger'),[10,'fresh coriander','F003192'],(20,'honey'),[2,'ground turmeric','F009335'],[15,'fish sauce','F008004'],(5,'soy'),(10,'oil')],['Blend onion, garlic, ginger, coriander, honey, turmeric, fish sauce, soy and oil into a paste. Coat chicken and refrigerate for 1 hour.','Wrap each piece with a washed food-safe pandan leaf and fasten with a toothpick. Keep leaf tips tucked away from the heating element.','Use the air fryer bake setting at 200°C for 15–18 minutes, turning once, until the chicken centre reaches 74°C. Remove leaves and toothpicks before eating.'],'Pandan leaves perfume small marinated chicken parcels while protecting their surface from direct heat.',wait=60,internal=74,allergens=['fish','soy','wheat','gluten'],equipment=['Food processor','Eight long food-safe pandan leaves','Wooden toothpicks'],nutritionNote='Boneless thigh replaces bone-in drumettes; ginger and coriander leaves simplify source root and lemongrass aromatics. Inedible pandan wrappers excluded from nutrient calculation.')
recipe('tuna-patties','Tuna and parmesan crumbed cakes',S,3,200,20,27,[[300,'tuna in brine, drained','F009285','','canned'],(10,'oil'),(10,'butter'),(80,'onion','Finely diced'),(80,'capsicum','Finely diced'),(5,'garlic','Grated'),(15,'lemon'),[50,'celery','F002390','Finely diced'],(10,'parsley','Chopped'),[40,'parmesan','F002479','Grated'],(1,'oregano'),(80,'crumbs'),(100,'egg')],['Soften onion, capsicum and garlic in butter and half the oil for 5–7 minutes. Cool, then mix with tuna, lemon, celery, parsley, oregano, eggs, half the parmesan and half the crumbs.','Form six cakes about 1.5 cm thick and refrigerate for 30 minutes. Combine remaining crumbs and parmesan and press onto both faces; brush with remaining oil.','Air fry at 200°C in two batches for 10 minutes each, turning carefully halfway, until golden and 75°C in the centre.'],'Tinned tuna, vegetables and parmesan form potato-free cakes with a crisp cheese and crumb coating.',wait=30,internal=75,allergens=['fish','egg','milk','wheat','gluten'],equipment=['Frying pan'],tags=['budget'],nutritionNote='Drained canned tuna weight is explicit. Three portions of two cakes; all coating counted and two air-fryer batches plus vegetable sauté included.')
recipe('bang-bang-shrimp','Starch-crisp prawns with chilli yoghurt sauce',S,4,180,20,16,[(600,'prawn'),[70,'cornflour','F003988'],(100,'yoghurt','Half for coating; half for sauce'),(50,'egg','Beaten'),(10,'oil'),(40,'mayo'),(20,'honey'),(15,'vinegar'),(1,'chilli'),[5,'fresh dill','F003509','Chopped'] ],['Coat dry prawns lightly in half the yoghurt. Dredge in cornflour, shake off loose starch and brush carefully with beaten egg and oil.','Air fry in two spaced batches at 180°C, checking after 5 minutes and extending to 8 minutes per batch if needed, until the prawns reach 63°C. Turn halfway.','Mix remaining yoghurt with mayonnaise, honey, vinegar, chilli and dill. Serve the sauce beside the hot prawns to keep their coating crisp.'],'A thin cornflour coating crisps around prawns served with a creamy sweet and sour chilli dip.',internal=63,allergens=['crustacean','milk','egg'],nutritionNote='Yoghurt replaces buttermilk and sour cream; a measured honey-chilli mixture replaces commercial sauces. Cornflour is maize starch. All coating counted.')
recipe('bruschetta-chicken','Tomato and basil stuffed chicken fans',C,4,190,20,15,[(600,'chicken','Four 150 g breasts'),(220,'freshTomato','Finely diced'),(30,'vinegar'),[15,'fresh basil','F000396','Chopped'],(10,'garlic','Grated'),(15,'oil'),(2,'oregano')],['Cut four deep slits across each chicken breast without cutting through the underside. Brush with half the oil and scatter with oregano.','Air fry chicken cut-side up at 190°C for 7 minutes. Meanwhile mix tomato, vinegar, basil, garlic and remaining oil.','Carefully spoon tomato mixture into the opened slits. Cook another 5–8 minutes until the thickest uncut meat reaches 74°C. Rest for 3 minutes.'],'Deep cuts in chicken breast hold a juicy tomato, basil and garlic filling as it finishes cooking.',preheat=3,wait=3,internal=74,allergens=[],nutritionNote='Defined 150 g breasts and vinegar replace unspecified rub and balsamic; cooking extended beyond source ten minutes when needed to reach the safety endpoint.')
recipe('chicken-patties-and-one-dish-chicken-rice','Mozzarella chicken schnitzel patties',C,4,180,20,24,[[450,'chicken mince','F002739'],(100,'mozz','Grated'),(50,'egg','Beaten'),(60,'crumbs'),(5,'garlic','Grated'),(5,'parsley','Chopped'),(5,'oil')],['Mix chicken, mozzarella, garlic and parsley until cohesive. Form eight flat patties no thicker than 1.5 cm and refrigerate for 20 minutes.','Dip in beaten egg and press into breadcrumbs on both sides. Brush lightly with oil.','Air fry at 180°C in two batches for about 12 minutes each, turning halfway, until the centres reach 74°C and the crumb coating is golden.'],'Chicken mince and mozzarella form soft-centred patties inside a light schnitzel-style crumb coating.',wait=20,internal=74,allergens=['milk','egg','wheat','gluten'],nutritionNote='Only the source chicken patty component is used. Breadcrumbs replace pork-rind coating; the separate rice component with inconsistent cooking time is omitted. Two batches included.')
recipe('air-fryer-lamb-salad','Warm lamb and crunchy cabbage salad',M,2,180,20,6,[[300,'cooked lean roast lamb','F005014','Thinly sliced','cooked'],(80,'lettuce','Shredded'),(150,'cabbage','Finely shredded'),(50,'onion','Thinly sliced'),(200,'freshTomato','Cut into wedges'),(150,'cucumber','Sliced'),(100,'yoghurt'),(15,'lemon'),(15,'mayo'),(3,'garlic','Grated')],['Arrange lettuce, cabbage, onion, tomato and cucumber on two plates. Mix yoghurt with lemon, mayonnaise and garlic to make a dressing.','Spread chilled cooked lamb in a shallow approved dish. Air fry at 180°C for 3–6 minutes, turning once, until piping hot and 75°C throughout.','Transfer hot lamb straight to the salad and spoon over the dressing. Eat immediately. Reheat only the amount you intend to eat.'],'Warm sliced roast lamb contrasts with crisp cabbage, cucumber and a garlic yoghurt dressing.',internal=75,allergens=['milk','egg'],equipment=['Shallow air-fryer-safe dish'],nutritionNote='Uses cooked lean lamb and measured salad weights. This is a meal made with safely refrigerated cooked lamb, not a raw lamb cooking recipe.')
recipe('air-fryer-messy-sloppy-joes-cheesy-fries','Beef and tomato loaded fries',Q,4,180,20,35,[(400,'beef'),(400,'tomato'),(40,'creamcheese'),(60,'cheddar','Grated'),(600,'potato','Cut into 1 cm chips'),(10,'oil'),(2,'oregano'),(2,'cumin'),(2,'paprika'),(1,'chilli')],['Toss chips with oil. Air fry at 160°C for 15–18 minutes, shaking twice, then transfer to a warm plate.','Put beef and tomatoes in a shallow approved dish. Air fry at 180°C for 10 minutes, breaking up the beef and stirring twice until it reaches 71°C. Stir in spices and cream cheese and cook 4 minutes more.','Return chips to the basket, spoon the hot beef mixture over them and scatter cheddar on top. Air fry at 200°C for 3 minutes until cheese melts and the filling reaches 75°C.'],'Tomato-rich beef mince and melted cheddar turn a batch of potato chips into a shared dinner.',internal=75,allergens=['milk'],equipment=['Shallow air-fryer-safe dish'],tags=['budget'],nutritionNote='Four portions replace the source two large servings; all oil and cheese counted. Fresh potato timing retained with checking for tenderness.')
